(x, y, t) => {
  const w1x = Math.sin(y*0.012+t*0.2)*20 + Math.cos(x*0.008-t*0.15)*15;
  const w1y = Math.cos(x*0.012-t*0.18)*20 + Math.sin(y*0.009+t*0.22)*15;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(my*0.02+t*0.35)*10 + Math.cos(mx*0.015-t*0.3)*8;
  const w2y = Math.cos(mx*0.02-t*0.32)*10 + Math.sin(my*0.018+t*0.38)*8;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [120+Math.sin(t*0.4)*80,60+Math.cos(t*0.3)*40,0.12,2.5],
    [360+Math.cos(t*0.5)*80,180+Math.sin(t*0.6)*40,0.11,2.2],
    [240+Math.sin(t*0.25+2)*120,120+Math.cos(t*0.45+1)*70,0.09,2.8],
    [80+Math.cos(t*0.35+1)*60,160+Math.sin(t*0.5+3)*50,0.065,1.8],
    [400+Math.sin(t*0.3+4)*70,40+Math.cos(t*0.55+2)*50,0.07,2.0],
    [200+Math.cos(t*0.28+5)*90,220+Math.sin(t*0.42)*60,0.055,2.3],
    [240+Math.sin(t*0.15)*160,120+Math.cos(t*0.2)*100,0.03,1.5],
    [240+Math.cos(t*0.18+3)*140,120+Math.sin(t*0.22+2)*90,0.025,1.3]
  ];
  let act=0, inh=0;
  for(let i=0;i<src.length;i++){
    const [sX,sY,f,sp]=src[i], d=Math.sqrt((sx-sX)**2+(sy-sY)**2), ph=i*1.1;
    act+=Math.sin(d*f-t*sp+ph)/Math.max(1,d*0.003);
    inh+=Math.sin(d*f*0.6+t*sp*0.5+ph+2)/Math.max(1,d*0.003);
  }
  act/=8; inh/=8;
  const bg1=(Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.038+t*0.95))/2;
  const bg2=Math.sin((sx+sy)*0.09+t*2)*0.3+Math.sin((sx-sy)*0.08-t*1.8)*0.3;
  const bg3=Math.sin(sx*0.06+Math.sin(sy*0.04+t)*2+t*1.5)*0.25;
  const bg=bg1+bg2+bg3;
  const cx=240,cy=120,dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3.5-t*1.3)+Math.sin(dist*0.035+ang*4.5-t)+Math.sin(dist*0.06-ang*2-t*1.8)*0.5)*0.3;
  const cX=(sx*0.08)|0, cY=(sy*0.08)|0;
  let minD=999,minD2=999;
  for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++){
    const nx=cX+dx,ny=cY+dy;
    const px=(nx+Math.sin(nx*1.7+ny*2.3+t*0.5)*0.4)*12.5;
    const py=(ny+Math.cos(nx*2.1+ny*1.5+t*0.4)*0.4)*12.5;
    const d=Math.sqrt((sx-px)**2+(sy-py)**2);
    if(d<minD){minD2=minD;minD=d;}else if(d<minD2)minD2=d;
  }
  const cellEdge=Math.min(1,(minD2-minD)*0.8);
  const reaction=Math.tanh((act-inh*0.65+bg*0.25+spiral)*2.5);
  const blend=reaction*0.7+(cellEdge-0.5)*0.3, v=blend*0.5+0.5;
  const pal=[[5,12,45],[10,35,78],[15,68,100],[22,108,118],[48,142,122],[125,168,98],[185,178,82],[215,168,68],[225,132,58],[198,88,68],[168,58,78],[122,38,68],[78,22,58],[38,16,50],[5,12,45]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15;
  const edgeGlow=Math.abs(reaction)>0.75?1.12+(Math.abs(reaction)-0.75)*0.4:1.0;
  const cellHL=cellEdge<0.3?1.0+(0.3-cellEdge)*0.3:1.0;
  const m=lum*edgeGlow*cellHL;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*m)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*m)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*m)|0
  ];
}
